60	export interface AgentEventCommon {
61	  /** Unique id for the event. */
62	  id: string;
63	  /** Identifies the subagent thread, omitted for "main thread" events. */
64	  threadId?: string;
65	  /** Identifies a particular stream of a particular thread. */
66	  streamId?: string | null;
67	  /** ISO Timestamp for the time at which the event occurred. */
68	  timestamp: string;
69	  /** The concrete type of the event. */
