15	/**
16	 * Populates a ToolDisplay object from a tool invocation and its result.
17	 * This serves as a centralized bridge during the migration to tool-controlled display.
18	 */
19	export function populateToolDisplay({
20	  name,
21	  invocation,
22	  resultDisplay,
23	  displayName,
24	  display: prevDisplay,
25	}: {
26	  name: string;
27	  invocation?: ToolInvocation<object, ToolResult>;
28	  resultDisplay?: ToolResultDisplay;
29	  displayName?: string;
30	  display?: ToolDisplay;
31	}): ToolDisplay {
32	  const display: ToolDisplay = {
33	    name: displayName || name,
34	    description: invocation?.getDescription?.(),
35	    ...prevDisplay,
36	  };
37	
38	  if (resultDisplay !== undefined && display.result === undefined) {
39	    display.result = toolResultDisplayToDisplayContent(resultDisplay);
40	  }
41	
42	  return display;
43	}
