45	/**
46	 * Converts a legacy ToolResultDisplay into the new DisplayContent format.
47	 */
48	export function toolResultDisplayToDisplayContent(
49	  resultDisplay: ToolResultDisplay,
50	): DisplayContent {
51	  if (typeof resultDisplay === 'string') {
52	    return { type: 'text', text: resultDisplay };
53	  }
54	
55	  // Handle FileDiff -> DisplayDiff
56	  if (
57	    typeof resultDisplay === 'object' &&
58	    resultDisplay !== null &&
59	    'fileDiff' in resultDisplay &&
60	    'newContent' in resultDisplay
61	  ) {
62	    return {
63	      type: 'diff',
64	      path: resultDisplay.filePath || resultDisplay.fileName,
65	      beforeText: resultDisplay.originalContent ?? '',
66	      afterText: resultDisplay.newContent,
67	    };
68	  }
69	
70	  // Fallback for other structured types (LsTool, GrepTool, etc.)
71	  // These will be fully migrated in Step 5.
72	  return {
73	    type: 'text',
74	    text: JSON.stringify(resultDisplay),
75	  };
76	}
